class PatchError(RuntimeError):
    pass


def _norm(raw: bytes) -> tuple[str, str, str]:
    """(LF text, newline, encoding marker: 'utf-8', 'utf-8-bom' or 'utf-16')."""
    if raw.startswith(b"\xff\xfe"):
        text, enc = raw[2:].decode("utf-16-le"), "utf-16"
    elif raw.startswith(b"\xef\xbb\xbf"):
        text, enc = raw[3:].decode("utf-8"), "utf-8-bom"
    else:
        text, enc = raw.decode("utf-8"), "utf-8"
    newline = "\r\n" if "\r\n" in text else "\n"
    return text.replace("\r\n", "\n"), newline, enc


def _encode(text: str, newline: str, enc: str) -> bytes:
    body = text.replace("\n", newline) if newline != "\n" else text
    if enc == "utf-16":
        return b"\xff\xfe" + body.encode("utf-16-le")
    return (b"\xef\xbb\xbf" if enc == "utf-8-bom" else b"") + body.encode("utf-8")


def _sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


@dataclass
class Planned:
    op: Op
    path: Path
    data: Optional[bytes]
    created: bool
    message: str


def _edited(op: Op, text: str, edits: tuple) -> str:
    for old, new in edits:
        count = text.count(old)
        if count != 1:
            raise PatchError(f"{op.path}: an edit anchor occurs {count} times; nothing has been written.")
        text = text.replace(old, new, 1)
    if _sha(text) != op.final_sha:
        raise PatchError(f"{op.path}: the edits did not produce the ARCH-50 file; nothing has been written.")
    return text


def plan(root: Path, op: Op) -> Planned:
    path = root / op.path
    if not path.exists():
        if op.kind == "new":
            text = op.text()
            if _sha(text) != op.final_sha:
                raise PatchError(f"{op.path}: the carried content is corrupt")
            return Planned(op, path, _encode(text, "\n", "utf-16" if op.encoding == "utf-16" else "utf-8"), True, "new file")
        raise PatchError(f"{op.path}: does not exist; this is not a {BASELINE} tree")
    try:
        text, newline, enc = _norm(path.read_bytes())
    except UnicodeDecodeError as exc:
        raise PatchError(f"{op.path}: not readable as text ({exc}); nothing has been written.") from exc
    actual = _sha(text)
    if actual == op.final_sha:
        if op.executable and os.name != "nt" and not os.access(path, os.X_OK):
            return Planned(op, path, path.read_bytes(), False, "executable bit restored")
        return Planned(op, path, None, False, "already applied")
    for base_sha, edits in op.variants:
        if actual == base_sha:
            result = _edited(op, text, edits) if edits else op.text()
            if _sha(result) != op.final_sha:
                raise PatchError(f"{op.path}: no content for this starting point")
            return Planned(op, path, _encode(result, newline, enc), False, "patched" if edits else "replaced")
    if LATER_MILESTONE.search(text):
        return Planned(op, path, None, False, "superseded by a later milestone")
    raise PatchError(
        f"{op.path}: sha256 {actual[:12]}... is not the {BASELINE} file or this "
        "package's result. It has local changes this script would discard. "
        "Nothing has been written."
    )


def _atomic_write(path: Path, data: bytes, executable: bool = False) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = stat.S_IMODE(path.stat().st_mode) if path.exists() else None
    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=".arch50-", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        if os.name != "nt":
            if mode is not None:
                os.chmod(tmp, (mode | 0o111) if executable else mode)
            elif executable:
                os.chmod(tmp, 0o755)
            else:
                os.chmod(tmp, 0o644)
        os.replace(tmp, path)
    except BaseException:
        if os.path.exists(tmp):
            os.unlink(tmp)
        raise


def apply(root: Path, *, check: bool) -> int:
    planned, problems = [], []
    for op in OPS:
        try:
            planned.append(plan(root, op))
        except PatchError as exc:
            problems.append(str(exc))
    for item in planned:
        print(f"  {item.message:<32} {item.op.path}")
    if problems:
        print("\nREFUSED:")
        for problem in problems:
            print(f"  {problem}")
        return 2
    writes = [p for p in planned if p.data is not None]
    print(f"\n{len(writes)} file(s) to write, {len(planned) - len(writes)} unchanged.")
    if check or not writes:
        return 0
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = HERE / ".arch50_apply_backup" / stamp
    manifest: dict[str, str] = {}
    modes: dict[str, int] = {}
    journal: list[tuple[Path, Optional[bytes], Optional[int]]] = []
    try:
        for item in writes:
            original = None if item.created else item.path.read_bytes()
            mode = None if item.created else stat.S_IMODE(item.path.stat().st_mode)
            if original is not None:
                (backup / item.op.path).parent.mkdir(parents=True, exist_ok=True)
                (backup / item.op.path).write_bytes(original)
            manifest[item.op.path] = "created" if item.created else "replaced"
            if mode is not None:
                modes[item.op.path] = mode
            journal.append((item.path, original, mode))
            _atomic_write(item.path, item.data, item.op.executable)
        backup.mkdir(parents=True, exist_ok=True)
        (backup / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
        (backup / "modes.json").write_text(json.dumps(modes, indent=2), encoding="utf-8")
    except BaseException as exc:
        for path, original, mode in reversed(journal):
            if original is None:
                if path.exists():
                    path.unlink()
            else:
                path.write_bytes(original)
                if mode is not None and os.name != "nt":
                    os.chmod(path, mode)
        shutil.rmtree(backup, ignore_errors=True)
        print(f"\nFAILED while writing ({exc}); every file this run wrote was restored.")
        return 1
    print(f"Wrote {len(writes)} file(s). Originals kept in {backup.relative_to(HERE)}.")
    print(f"Next: alembic upgrade {HEAD_RELEASE}  (run_arch50.ps1 does this)")
    return 0


def rollback(root: Path) -> int:
    base = HERE / ".arch50_apply_backup"
    runs = sorted(p for p in base.glob("*") if (p / "manifest.json").exists()) if base.exists() else []
    if not runs:
        print("No ARCH-50 apply backup found; nothing to roll back.")
        return 1
    run = runs[-1]
    manifest = json.loads((run / "manifest.json").read_text(encoding="utf-8"))
    modes = json.loads((run / "modes.json").read_text(encoding="utf-8")) if (run / "modes.json").exists() else {}
    finals = {op.path: op.final_sha for op in OPS}
    kept = 0
    for rel, what in manifest.items():
        target = root / rel
        if what == "replaced":
            _atomic_write(target, (run / rel).read_bytes())
            if rel in modes and os.name != "nt":
                os.chmod(target, modes[rel])
            print(f"  restored  {rel}")
        elif target.exists():
            text, _, _ = _norm(target.read_bytes())
            if _sha(text) == finals.get(rel):
                target.unlink()
                print(f"  removed   {rel}")
                parent = target.parent
                while parent != root and parent.exists() and not any(parent.iterdir()):
                    parent.rmdir()
                    parent = parent.parent
            else:
                kept += 1
                print(f"  KEPT      {rel} (edited since the apply; delete it yourself)")
    if kept == 0:
        shutil.rmtree(run)
        if base.exists() and not any(base.iterdir()):
            base.rmdir()
        print("  removed   the backup snapshot; nothing is left behind")
    else:
        print(f"  KEPT      the backup snapshot {run.name} ({kept} file(s) changed after the apply)")
    print(
        "\nCode restored to the state before the last apply. The DATABASE is not\n"
        f"touched. Take the database back BEFORE the code: `alembic downgrade {HEAD_BEFORE}`\n"
        "needs this package's migration file, which the rollback removes. If the\n"
        "database is still at the ARCH-50 revision, re-apply, downgrade, roll back:\n"
        "    python apply_arch50.py\n"
        f"    python -m alembic downgrade {HEAD_BEFORE}   (drops the fourteen ARCH-50 tables)\n"
        "    python apply_arch50.py --rollback\n"
        "(run_arch50.ps1 -Rollback -WithDatabase does the downgrade first.)"
    )
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="Apply ARCH-50")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--rollback", action="store_true")
    parser.add_argument("--list", action="store_true")
    parser.add_argument("--root", default=str(HERE.parent), help="repository root (default: ..)")
    args = parser.parse_args()
    root = Path(args.root).resolve()
    if args.list:
        for op in OPS:
            print(f"  {op.kind:<8} {op.path}")
        return 0
    if args.rollback:
        return rollback(root)
    print(f"ARCH-50 apply ({'check' if args.check else 'write'}) against {root}")
    return apply(root, check=args.check)


if __name__ == "__main__":
    sys.exit(main())
